import{_ as o,C as a,c as n,o as s,aj as r,G as t,w as h}from"./chunks/framework.Bfdr4H5E.js";const y=JSON.parse('{"title":"Volume","description":"","frontmatter":{"outline":"deep","prev":{"text":"Fibonacci Retracement","link":"/trading-with-pav/fibonacci-retracement"},"next":{"text":"Volume Price Analysis","link":"/trading-with-pav/volume-price-analysis"}},"headers":[],"relativePath":"trading-with-pav/volume.md","filePath":"trading-with-pav/volume.md"}'),u={name:"trading-with-pav/volume.md"};function m(d,e,c,f,p,w){const l=a("GraphComment"),i=a("ClientOnly");return s(),n("div",null,[e[0]||(e[0]=r('<h1 id="volume" tabindex="-1">Volume <a class="header-anchor" href="#volume" aria-label="Permalink to &quot;Volume&quot;">​</a></h1><p>In this article will dive into the volume which is the fuel of the market without volume price wouldn’t move. Will explore how to use volume to our advantage in Price Action, Big institutions and conform trades.</p><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#volume-1">Volume</a></li><li><a href="#why-is-volume-important">Why is Volume important ?</a></li><li><a href="#price-and-volume">Price and Volume</a></li><li><a href="#understanding-wyckoff-3-rules">Understanding Wyckoff 3 Rules</a><ul><li><a href="#the-law-of-supply-and-demand">The Law of Supply and Demand</a></li><li><a href="#the-law-of-cause-and-effect">The Law of Cause and Effect</a></li><li><a href="#the-law-of-effort-vs-result">The Law of Effort vs Result</a></li></ul></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="volume-1" tabindex="-1">Volume <a class="header-anchor" href="#volume-1" aria-label="Permalink to &quot;Volume&quot;">​</a></h2><ul><li>Volumes are the most important information the market can give us.</li><li>Why is it so important? <ul><li>It is because around 80 % of all trades and volumes are made by the big financial institutions (the big guys/smart money)</li><li>They move and manipulate the markets.</li><li>They have the best trading experts, technology, algorithms and also extreme amounts of money.</li><li>Having so much money is also a problem though as we discussed in [[Price Action]].</li><li>It is hard for them to move such amounts, to invest them and also to hide their trading intentions.</li><li>Big institutions can’t just buy 50,00,000 shares of State bank of India with one-click.</li><li>They need to enter their positions slowly, unnoticed. Still, they will never be able to hide.</li><li>Their volumes will always be visible, and we will always be able to track them.</li></ul></li><li>How to Track volume? <ul><li>With Volume Profile (In Volume 5) &amp;</li><li>Volume (Bar volume/Volume at Time). Before learning Volume Profile lets start with volume.</li></ul></li></ul><h2 id="why-is-volume-important" tabindex="-1">Why is <strong>Volume</strong> important ? <a class="header-anchor" href="#why-is-volume-important" aria-label="Permalink to &quot;Why is **Volume** important ?&quot;">​</a></h2><ul><li>Volume applies to all markets and is equally valuable, whether there is market manipulation or not.</li><li>Volume reveals buying and selling, when the market is running out of steam.</li><li>It reveals whether buying interest is rising or falling on a daily basis.</li><li>It reveals all the subtleties (features) of pull backs and reversals on tick charts and all time-frame charts from minutes to hours.</li><li>Volume is the fuel that drives the market.</li><li>Volume reveals when the major operators are moving in and out of the market.</li><li>Without volume, nothing moves, and if it does move and the volume is not in agreement, then there is something wrong, and an alarm bells should ring!</li></ul><h2 id="price-and-volume" tabindex="-1">Price and Volume <a class="header-anchor" href="#price-and-volume" aria-label="Permalink to &quot;Price and Volume&quot;">​</a></h2><blockquote><p>“Trading and investing is like any other pursuit — the longer you stay at it the more technique you acquire, and anybody who thinks he knows of a shortcut that will not involve ‘sweat of the brow’ is sadly mistaken”</p><p>– Richard Wyckoff</p></blockquote><ul><li>Whilst this sentiment could be applied to almost any endeavor in life, it is particularly relevant in the study of price and volume.</li><li>The basic laws of supply and demand with price, volume, time and trend at its heart, Wyckoff detailed three basic laws. <ol><li>The Law of Supply and Demand</li><li>The Law of Cause and Effect</li><li>The Law of Effort vs Result</li></ol></li></ul><h2 id="understanding-wyckoff-3-rules" tabindex="-1">Understanding Wyckoff 3 Rules <a class="header-anchor" href="#understanding-wyckoff-3-rules" aria-label="Permalink to &quot;Understanding Wyckoff 3 Rules&quot;">​</a></h2><h3 id="the-law-of-supply-and-demand" tabindex="-1">The Law of Supply and Demand <a class="header-anchor" href="#the-law-of-supply-and-demand" aria-label="Permalink to &quot;The Law of Supply and Demand&quot;">​</a></h3><ul><li>When demand is greater than supply, then prices will rise to meet this demand, and<br> conversely when supply is greater then demand then prices will fall, with the over supply being absorbed as a result.</li><li>Consider the winter sales! Prices fall and the buyers come in to absorb over supply.</li></ul><h3 id="the-law-of-cause-and-effect" tabindex="-1">The Law of Cause and Effect <a class="header-anchor" href="#the-law-of-cause-and-effect" aria-label="Permalink to &quot;The Law of Cause and Effect&quot;">​</a></h3><ul><li>In order to have an effect, you must first have a cause and the effect will be in direct proportion to the cause.</li><li>In other words, a small amount of volume activity will only result in a small amount of price action.</li><li>This law is applied to a number of price bars and will dictate the extent of any subsequent trend.</li><li>If the cause is large, then the effect will be large as well.</li><li>If the cause is small, then the effect will also be small.</li><li>The simplest analogy here is of a wave at sea.</li><li>A large wave hitting a vessel will see the ship roll violently, whereas a small wave would have little or no effect.</li></ul><h3 id="the-law-of-effort-vs-result" tabindex="-1">The Law of Effort vs Result <a class="header-anchor" href="#the-law-of-effort-vs-result" aria-label="Permalink to &quot;The Law of Effort vs Result&quot;">​</a></h3><ul><li>The price action on the chart must reflect the volume action.</li><li>The two should always be in harmony with one another, with the effort (which is the volume) seen as the result (which is the consequent price action).</li><li>If they don’t then there is anomaly &amp; we have to spot such anomalies to trade right.</li></ul><p>That’s it for this article next will start with VPA i.e. Volume Price Analysis.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',19)),t(i,null,{default:h(()=>[t(l)]),_:1})])}const b=o(u,[["render",m]]);export{y as __pageData,b as default};
